    st.set_page_config(layout="wide");
    st.title("Welcome to your Jac MCP Chatbot!");
    # Initialize chat history
    if "messages" not in st.session_state {
        st.session_state.messages = [];
    }

    uploaded_file = st.file_uploader('Upload PDF');
